{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "SageMaker action uses an unrestricted resource",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy permits sagemaker:CreatePresignedNotebookInstanceUrl against "*", allowing presigned access URLs to be created for any notebook instance accessible to the policy. This action supports resource-level permissions and should be scoped to SageMaker notebook instances in the current account and region."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Sensitive SageMaker access is allowed without resource constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "Creating a presigned notebook URL can provide direct notebook access, but the policy applies the permission without account or region constraints. The unrestricted ListNotebookInstances action is also combined with it, preventing effective resource scoping."
    }
  ],
  "patched_code": "data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:sagemaker:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:notebook-instance/*"
      },
      {
        Effect = "Allow"
        Action = [
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "*"
      },
    ]
  })
}
",
  "fix_summary": "Separated the resource-scopable presigned URL action from ListNotebookInstances, which requires a wildcard resource. Restricted presigned URL creation to notebook instances in the current AWS account, region, and partition."
}
